const PROGRESS_KEY="baseframe-kg-course";
const modules = [{"number": "01", "title": "What is a knowledge graph?", "description": "Explain entities, relationships, properties, and evidence from first principles.", "icon": "◇", "lessons": [{"id": "kg-1", "title": "What is a knowledge graph?", "summary": "Explain entities, relationships, properties, and evidence from first principles.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Explain entities, relationships, properties, and evidence from first principles.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Entity", "definition": "A thing in the domain with a stable identity.", "explanation": "An entity represents something you need to distinguish and talk about: a product, API endpoint, guide, team, or policy. Its identifier remains stable even when its display name changes. A label such as “Jobs” is not enough if multiple products have different Jobs endpoints. Resolve identities before joining information from sources.", "example": "relay:endpoint:create-job identifies POST /v2/jobs, while relay:topic:quickstart identifies its documentation.", "caution": "Do not merge two entities merely because their names look similar."}, {"term": "Relationship", "definition": "A typed connection between identifiable entities.", "explanation": "A relationship states how one entity connects to another. The type matters: a guide DOCUMENTS an endpoint, a team OWNS a guide, and an endpoint BELONGS_TO a product. These are different meanings and support different questions. A knowledge graph makes these connections explicit rather than leaving the reader to infer them from a folder or document.", "example": "Quickstart —DOCUMENTS→ CreateJob; DocsTeam —OWNS→ Quickstart.", "caution": "An AI-proposed relationship is a candidate until the evidence and meaning are reviewed."}, {"term": "Property and provenance", "definition": "Attributes describe a record; provenance identifies its evidence and history.", "explanation": "Properties can describe an entity or a relationship. version=2 describes applicability; reviewed_at describes review timing. Provenance connects a graph assertion to its source, supporting passage, reviewer, and status. It allows a user to ask not only what is connected, but why the connection should be trusted.", "example": "The DOCUMENTS relationship references R1 and the approved topic record, with status=proposed until review.", "caution": "A stored source ID does not prove that its content supports the relationship."}], "body": ["A knowledge graph is a representation of a domain as identifiable things and meaningful relationships, usually with attributes and evidence. It is useful for questions that depend on connections: which guides describe this capability, who maintains them, and what must change if the capability changes? The graph is the representation; a graph database or query engine is a technology used to store or query that representation.", "In a property graph, nodes typically represent entities and edges represent typed connections; both may carry properties. RDF expresses statements as subject–predicate–object triples and can use identifiers and vocabularies to express shared meaning. These are related modeling approaches with different implementations. Neither turns weak evidence into truth automatically.", "A graph drawn on screen is only one view of the records. The product must also preserve IDs, relationship meanings, applicable versions, provenance, permissions, and lifecycle rules. A simple spreadsheet can be enough to learn the model before selecting a graph engine."], "workflow": ["Choose a domain and one question.", "List the entities needed to answer it.", "Assign stable IDs and types.", "Connect them with precise relationship names.", "Attach evidence and review state to each assertion."], "deep_dive": [], "annotated": {"code": "Product: Relay v2\nEndpoint: CreateJob (POST /v2/jobs)\nTopic: First-job quickstart\nTeam: Docs Integrations\n\nQuickstart —DOCUMENTS→ CreateJob\nCreateJob —BELONGS_TO→ Relay v2\nDocs Integrations —OWNS→ Quickstart", "notes": ["Nodes are things; relationship types explain meaning.", "A diagram is illustrative until its records have supporting evidence.", "Ownership is a teaching assumption requiring verification in a real organization."]}, "exercise": {"task": "Identify four entities, three relationships, and two properties in this example. Explain why a keyword list is not the same graph.", "hint": "Look for things, named connections, and descriptive values.", "solution": "Entities include the product, endpoint, topic, and team. Relationships are DOCUMENTS, BELONGS_TO, and OWNS. Properties can include version and review status. A keyword list classifies words but does not encode these typed connections or stable identities."}, "example": {"title": "Relay documentation graph · fictional project", "content": "Product: Relay v2\nEndpoint: CreateJob (POST /v2/jobs)\nTopic: First-job quickstart\nTeam: Docs Integrations\n\nQuickstart —DOCUMENTS→ CreateJob\nCreateJob —BELONGS_TO→ Relay v2\nDocs Integrations —OWNS→ Quickstart"}, "lab": {"task": "Identify four entities, three relationships, and two properties in this example. Explain why a keyword list is not the same graph.", "steps": ["Choose a domain and one question.", "List the entities needed to answer it.", "Assign stable IDs and types.", "Connect them with precise relationship names.", "Attach evidence and review state to each assertion."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["Nodes are things; relationship types explain meaning.", "A diagram is illustrative until its records have supporting evidence.", "Ownership is a teaching assumption requiring verification in a real organization.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "Which statement defines a knowledge graph best?", "options": ["A list of keywords", "Entities connected through meaningful, typed relationships", "A PDF folder", "A model’s training data"], "answer": 1, "explanation": "Entities include the product, endpoint, topic, and team. Relationships are DOCUMENTS, BELONGS_TO, and OWNS. Properties can include version and review status. A keyword list classifies words but does not encode these typed connections or stable identities."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}, {"number": "02", "title": "Why does a knowledge graph matter?", "description": "Decide whether relationships solve a real knowledge problem.", "icon": "◇", "lessons": [{"id": "kg-2", "title": "Why does a knowledge graph matter?", "summary": "Decide whether relationships solve a real knowledge problem.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Decide whether relationships solve a real knowledge problem.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Traversal", "definition": "Following selected relationship types to answer a question.", "explanation": "Traversal moves from a starting entity through connections relevant to a task. If an endpoint changes, follow DOCUMENTS in reverse to find its topics, then OWNS in reverse to find responsible teams. The allowed path encodes domain meaning; it does not require a model to guess connections from prose every time.", "example": "Changed endpoint → affected topic → accountable team.", "caution": "Traversal returns the relationships stored in the graph; missing relationships produce incomplete answers."}, {"term": "Change-impact analysis", "definition": "Finding what depends on a changed entity.", "explanation": "Impact analysis uses dependencies to identify review work. A product field may be documented in multiple topics, examples, and training modules. Modeling those dependencies makes the change scope inspectable and repeatable. The result is a candidate impact set that owners review; it does not automatically prove every item requires the same change.", "example": "A changed job.state field affects reference, polling examples, evaluation cases, and training.", "caution": "A graph requires maintenance; an outdated dependency can miss a critical update."}], "body": ["Use a knowledge graph when relationships are central to the question. “What is the source_url type?” can be answered from a reference table. “Which approved guides, examples, and tests depend on this field, and who owns them?” is naturally a connected-data question. That difference should drive architecture.", "The graph can join knowledge from documentation, source contracts, ownership records, and review systems. This helps people navigate related material, assess change impact, and retrieve context for an assistant. It can also expose missing ownership and contradictory version links. These benefits depend on coverage, identity resolution, and current evidence.", "There is a cost: designing and governing the schema, ingesting sources, resolving IDs, reviewing relationships, applying permissions, and maintaining updates. Start with a dependency table if it answers the question. Add graph storage or traversal when the connected queries justify it. The graph is optional infrastructure rather than a prerequisite for all AI content."], "workflow": ["Name a relationship-dependent question.", "Find how it is answered today.", "Model the shortest useful path.", "Check missing or stale relationships.", "Compare value and maintenance effort with a simpler table."], "deep_dive": [], "annotated": {"code": "Question: Which assets must be reviewed if job.state changes?\nStart: relay:field:job-state\nFollow: topic DEPENDS_ON field\nThen: team OWNS topic\nFilter: applicable_version=2; status=approved\nResult: candidate review list with owners and evidence", "notes": ["The business question defines the graph path.", "Filters prevent irrelevant versions entering the answer.", "An empty result can mean missing data, not no impact."]}, "exercise": {"task": "Choose whether a graph is justified for (a) one static glossary and (b) 800 topics with shared fields and several owners. Explain the tradeoff.", "hint": "Relationship volume and changing dependencies matter more than the AI label.", "solution": "A static glossary can usually use a table. The larger changing topic network may justify a graph for impact and ownership traversal, provided IDs and dependencies are maintained. Size alone is not enough: demonstrate a recurring connected-data question."}, "example": {"title": "Relay documentation graph · fictional project", "content": "Question: Which assets must be reviewed if job.state changes?\nStart: relay:field:job-state\nFollow: topic DEPENDS_ON field\nThen: team OWNS topic\nFilter: applicable_version=2; status=approved\nResult: candidate review list with owners and evidence"}, "lab": {"task": "Choose whether a graph is justified for (a) one static glossary and (b) 800 topics with shared fields and several owners. Explain the tradeoff.", "steps": ["Name a relationship-dependent question.", "Find how it is answered today.", "Model the shortest useful path.", "Check missing or stale relationships.", "Compare value and maintenance effort with a simpler table."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["The business question defines the graph path.", "Filters prevent irrelevant versions entering the answer.", "An empty result can mean missing data, not no impact.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "What most strongly justifies a graph?", "options": ["A desire to use AI", "A recurring question that requires connected facts across sources", "Having any text", "Needing a prettier diagram"], "answer": 1, "explanation": "A static glossary can usually use a table. The larger changing topic network may justify a graph for impact and ownership traversal, provided IDs and dependencies are maintained. Size alone is not enough: demonstrate a recurring connected-data question."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}, {"number": "03", "title": "Taxonomy, metadata, ontology, graph, and vector search", "description": "Explain related concepts without treating them as interchangeable.", "icon": "◇", "lessons": [{"id": "kg-3", "title": "Taxonomy, metadata, ontology, graph, and vector search", "summary": "Explain related concepts without treating them as interchangeable.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Explain related concepts without treating them as interchangeable.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Taxonomy and metadata", "definition": "Taxonomy supplies governed categories; metadata assigns contextual attributes.", "explanation": "A taxonomy might define product areas and document types. Metadata records product=Relay, type=procedure, version=2, status=approved, and owner. Categories make classification consistent; metadata makes applicability and lifecycle explicit. Neither alone says that a specific guide documents a specific endpoint.", "example": "Category: API documentation. Topic metadata: Relay, v2, approved.", "caution": "An uncontrolled list of tags can contain synonyms and ambiguous values that weaken filters."}, {"term": "Ontology and schema", "definition": "A schema specifies allowed record shapes; an ontology expresses domain meaning and constraints.", "explanation": "A graph schema defines entity types, properties, and allowed relationships. An ontology can go further by describing shared meanings, hierarchies, and logical constraints. These terms overlap in practice, but a JSON shape alone is not a complete domain ontology. Start with a small documented model and add semantics needed for actual use.", "example": "Topic DOCUMENTS Endpoint; Team OWNS Topic; each approved relationship requires source evidence.", "caution": "A sophisticated ontology is unnecessary if a simple typed model solves the task."}, {"term": "Vector search and graph retrieval", "definition": "Vector search finds similarity; graph retrieval follows explicit connections.", "explanation": "Embeddings represent content numerically so a system can rank similarity to a query. Graph retrieval follows modeled relations such as depends_on or owned_by. They can complement each other: vector search finds a passage about job failures, while a graph identifies its version, related endpoint, and owner. Neither inherently guarantees factuality or permission compliance.", "example": "Semantic search finds a troubleshooting passage; a graph path links it to the approved v2 endpoint.", "caution": "A similar passage can be obsolete, and a graph relation can be wrong. Both need eligibility checks."}], "body": ["Think of these layers as answers to different questions. Taxonomy asks “Which category?” Metadata asks “What context and status?” A schema asks “What shape is valid?” An ontology asks “What does this domain mean and which constraints apply?” A graph asks “How do these things connect?” Vector search asks “Which content is semantically similar?”", "A combined system might classify a topic, attach metadata, validate its schema, connect it to a capability, index its text, and select evidence through both similarity and relationship filters. That combination is an architectural choice, not a requirement to implement every technology at once.", "The smallest useful pilot may use Markdown, controlled front matter, an edge table, and manual retrieval tests. It can demonstrate the information requirements before the team invests in a platform."], "workflow": ["List questions the system must answer.", "Map each question to classification, context, relationships, or similarity.", "Define the minimum data model.", "Choose only the needed retrieval methods.", "Test the combined result and its limitations."], "deep_dive": [], "annotated": {"code": "Taxonomy: documentation > API > procedure\nMetadata: product=Relay; version=2; status=approved\nSchema: Topic has id, type, source_ids\nGraph: Quickstart DOCUMENTS CreateJob\nVector search: find passages similar to “submit my first task”\nEligibility: authorized, approved, applicable evidence only", "notes": ["The same topic participates in several layers.", "Similarity does not replace applicability filters.", "The graph records specific relations rather than only categories."]}, "exercise": {"task": "A system has tags and embeddings. Does it already have a knowledge graph? Explain what would need to be added.", "hint": "Look for stable identities and typed entity connections.", "solution": "Not necessarily. Tags classify and embeddings represent similarity. A knowledge graph requires identifiable domain entities and meaningful relationships, with the evidence and governance required by the use case. A vector index might link records, but links alone do not establish domain semantics."}, "example": {"title": "Relay documentation graph · fictional project", "content": "Taxonomy: documentation > API > procedure\nMetadata: product=Relay; version=2; status=approved\nSchema: Topic has id, type, source_ids\nGraph: Quickstart DOCUMENTS CreateJob\nVector search: find passages similar to “submit my first task”\nEligibility: authorized, approved, applicable evidence only"}, "lab": {"task": "A system has tags and embeddings. Does it already have a knowledge graph? Explain what would need to be added.", "steps": ["List questions the system must answer.", "Map each question to classification, context, relationships, or similarity.", "Define the minimum data model.", "Choose only the needed retrieval methods.", "Test the combined result and its limitations."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["The same topic participates in several layers.", "Similarity does not replace applicability filters.", "The graph records specific relations rather than only categories.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "Which method directly answers “Who owns this topic?” when ownership is modeled?", "options": ["Vector similarity alone", "An OWNS relationship traversal", "A word count", "A readability score"], "answer": 1, "explanation": "Not necessarily. Tags classify and embeddings represent similarity. A knowledge graph requires identifiable domain entities and meaningful relationships, with the evidence and governance required by the use case. A vector index might link records, but links alone do not establish domain semantics."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}, {"number": "04", "title": "Design a small graph schema", "description": "Model identities, relationship direction, properties, and evidence.", "icon": "◇", "lessons": [{"id": "kg-4", "title": "Design a small graph schema", "summary": "Model identities, relationship direction, properties, and evidence.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Model identities, relationship direction, properties, and evidence.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Stable identity", "definition": "An identifier that distinguishes the same entity across sources and changes.", "explanation": "IDs should be durable and unambiguous. Use namespaces or compound identifiers where appropriate, such as relay:v2:endpoint:create-job. Normalize aliases to the same entity only when evidence confirms equivalence. Keep names as properties that may change without breaking relationships.", "example": "“Create job API” and “POST /v2/jobs” can share an ID after verification.", "caution": "Do not merge v1 and v2 behavior simply because the endpoint purpose is similar."}, {"term": "Relationship schema", "definition": "The allowed meaning, endpoints, direction, and properties of an edge.", "explanation": "Define each relation in plain language. DOCUMENTS connects a Topic to an Endpoint; OWNS connects a Team to a Topic; DEPENDS_ON connects an asset to a capability or field. Direction should be consistent so queries are predictable. Record source ID, evidence location, applicability, review state, and reviewer where required.", "example": "DOCUMENTS: Topic → Endpoint; approved evidence must show the topic covers that endpoint.", "caution": "A generic RELATED_TO relation is easy to populate but often too vague for operational questions."}], "body": ["Begin with one question and three or four entity types. Each type should exist because it contributes to an answer. Define IDs, fields, relationships, required evidence, and constraints. Then model one successful example and one invalid example to test whether the definitions are clear.", "Define cardinality only when the domain supports it. A topic may have several owning contributors but one accountable owner; your schema must distinguish contribution from accountability rather than forcing reality into a simplistic one-to-one relation. Product and version scope may belong on entities, edges, or both depending on the model. Explain that choice.", "The teaching graph is a property-style model. RDF systems can express similar domain assertions using IRIs and predicates, with vocabulary and validation choices suited to that implementation. Choosing a syntax is secondary to making meanings and review rules clear."], "workflow": ["Write the business question.", "Define entity types and stable IDs.", "Specify relation meaning and direction.", "Add evidence, applicability, and status fields.", "Test valid and invalid sample records."], "deep_dive": [], "annotated": {"code": "{\"from\":\"relay:topic:quickstart-v2\", \"type\":\"DOCUMENTS\",\n \"to\":\"relay:v2:endpoint:create-job\",\n \"source_id\":\"R1\", \"evidence\":\"POST /v2/jobs contract\",\n \"status\":\"proposed\", \"applicable_version\":\"2\"}", "notes": ["The IDs identify records, not display labels.", "Proposed status prevents extraction from becoming automatic approval.", "The topic’s own coverage needs evidence too; R1 alone defines the endpoint, not a finished guide."]}, "exercise": {"task": "Create schemas for Product, Endpoint, Topic, and Team, plus three relationship types. Add a rule preventing a v1 topic from being approved as v2 documentation.", "hint": "Applicability can be validated on connected records and relationships.", "solution": "Require explicit version applicability on topics/endpoints and reject a DOCUMENTS edge whose version scopes conflict. Allow a multi-version topic only if evidence explicitly supports those versions. Keep ownership assumptions proposed until verified."}, "example": {"title": "Relay documentation graph · fictional project", "content": "{\"from\":\"relay:topic:quickstart-v2\", \"type\":\"DOCUMENTS\",\n \"to\":\"relay:v2:endpoint:create-job\",\n \"source_id\":\"R1\", \"evidence\":\"POST /v2/jobs contract\",\n \"status\":\"proposed\", \"applicable_version\":\"2\"}"}, "lab": {"task": "Create schemas for Product, Endpoint, Topic, and Team, plus three relationship types. Add a rule preventing a v1 topic from being approved as v2 documentation.", "steps": ["Write the business question.", "Define entity types and stable IDs.", "Specify relation meaning and direction.", "Add evidence, applicability, and status fields.", "Test valid and invalid sample records."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["The IDs identify records, not display labels.", "Proposed status prevents extraction from becoming automatic approval.", "The topic’s own coverage needs evidence too; R1 alone defines the endpoint, not a finished guide.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "Why define relationship direction?", "options": ["To decorate the graph", "To make meaning and query paths consistent", "To increase text length", "To eliminate review"], "answer": 1, "explanation": "Require explicit version applicability on topics/endpoints and reject a DOCUMENTS edge whose version scopes conflict. Allow a multi-version topic only if evidence explicitly supports those versions. Keep ownership assumptions proposed until verified."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}, {"number": "05", "title": "Build the graph from source records", "description": "Extract candidates, attach evidence, review, and export a small graph.", "icon": "◇", "lessons": [{"id": "kg-5", "title": "Build the graph from source records", "summary": "Extract candidates, attach evidence, review, and export a small graph.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Extract candidates, attach evidence, review, and export a small graph.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Candidate extraction", "definition": "Turning source material into proposed entities and relationships.", "explanation": "Extraction can be manual, rule-based, or AI-assisted. First identify mentions and resolve entities, then propose meaningful relationships with exact evidence. An extractor may confuse a discussion of a future feature with current behavior. Preserve source version and review status so proposed material does not silently enter trusted queries.", "example": "R1 establishes that CreateJob is a Relay v2 endpoint. A separate topic record establishes which guide documents it.", "caution": "AI output that conforms to JSON can still contain invented facts."}, {"term": "Review and validation", "definition": "Checking that records satisfy schema and that evidence supports meaning.", "explanation": "Structural checks inspect required fields, allowed types, valid IDs, and duplicate edges. Evidence checks inspect whether the passage supports the assertion and whether it is applicable and authorized. Reviewers resolve ambiguity, approve justified candidates, reject unsupported ones, and capture reasons for corrections.", "example": "Reject OWNS(DocsTeam, Quickstart) if no approved ownership record supports it.", "caution": "An exact quote can be real but still fail to support the claimed relationship."}], "body": ["Build the first graph with a tiny corpus: the Relay contract, one completed quickstart, one reference topic, and an explicit ownership record. Create a source registry before extraction. Each source has identity, revision, authority, owner, access, and status. This makes later review and retirement possible.", "You can start in the Baseframe Knowledge Graph Studio: add a source excerpt, enter entity pairs and a typed relationship, attach a supporting quote, and review the candidate. Export a backup. This course teaches the workflow; the hosted studio is a browser-based prototype, and the separate repository may have different capabilities. Inspect the specific tool before relying on production persistence or connectors.", "One implementation pattern maps normalized relational records into a graph schema and queries them. For a documentation corpus, you still need normalized entity and relationship records before mapping tables. A graph engine does not automatically supply source authority or review governance. Start with a small mapping exercise and verify IDs, joins, and counts."], "workflow": ["Register four source records.", "Extract entity candidates with IDs.", "Create relationship candidates with supporting passages.", "Validate schema, deduplicate, and review evidence.", "Approve valid candidates, reject others, and export the result."], "deep_dive": [], "annotated": {"code": "1. sources: source_id, revision, status, text\n2. entities: entity_id, type, name, version\n3. relationships: from_id, relation, to_id, source_id, evidence, review_status\n4. review: candidate_id, reviewer, decision, reason\n5. export: entities + approved relationships + provenance", "notes": ["The tables can be a spreadsheet or normalized database.", "The review log preserves reasons, not just a green check.", "Exported data must retain evidence and applicable permissions."]}, "exercise": {"task": "Build three approved relationships and one rejected candidate. Use a separate synthetic ownership source instead of assuming a team owns a guide.", "hint": "A candidate can be rejected for unsupported meaning even when its fields are complete.", "solution": "Create evidence for endpoint-product membership, topic-endpoint coverage, and an explicitly stated ownership assignment. Reject a completion-SLA edge because R1 contains no guarantee. Document source IDs, review decisions, and applicability for every accepted relation."}, "example": {"title": "Relay documentation graph · fictional project", "content": "1. sources: source_id, revision, status, text\n2. entities: entity_id, type, name, version\n3. relationships: from_id, relation, to_id, source_id, evidence, review_status\n4. review: candidate_id, reviewer, decision, reason\n5. export: entities + approved relationships + provenance"}, "lab": {"task": "Build three approved relationships and one rejected candidate. Use a separate synthetic ownership source instead of assuming a team owns a guide.", "steps": ["Register four source records.", "Extract entity candidates with IDs.", "Create relationship candidates with supporting passages.", "Validate schema, deduplicate, and review evidence.", "Approve valid candidates, reject others, and export the result."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["The tables can be a spreadsheet or normalized database.", "The review log preserves reasons, not just a green check.", "Exported data must retain evidence and applicable permissions.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "What should happen to an AI-extracted relationship first?", "options": ["Treat it as approved truth", "Validate it as a candidate against evidence and schema", "Delete its source link", "Publish it without review"], "answer": 1, "explanation": "Create evidence for endpoint-product membership, topic-endpoint coverage, and an explicitly stated ownership assignment. Reject a completion-SLA edge because R1 contains no guarantee. Document source IDs, review decisions, and applicability for every accepted relation."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}, {"number": "06", "title": "Query, evaluate, and maintain the graph", "description": "Answer connected questions while retaining evidence and checking coverage.", "icon": "◇", "lessons": [{"id": "kg-6", "title": "Query, evaluate, and maintain the graph", "summary": "Answer connected questions while retaining evidence and checking coverage.", "time": "20–30 min reading + practice", "level": "Beginner to practitioner", "objectives": ["Answer connected questions while retaining evidence and checking coverage.", "Explain the distinction using a concrete example", "Create and inspect a small evidence-backed artifact"], "concepts": [{"term": "Graph query", "definition": "A pattern describing which entities and relations to return.", "explanation": "A query selects a path through the model and applies conditions. In a property-graph language, a pattern can match a Topic connected by DOCUMENTS to an Endpoint. Query the schema you actually have; names and syntax differ by engine. The course example is illustrative Cypher-style syntax, not a compatibility guarantee for every product.", "example": "Find topics that DOCUMENTS the changed endpoint and teams that OWNS those topics.", "caution": "A query returning rows does not prove complete coverage or valid evidence."}, {"term": "Graph evaluation and lifecycle", "definition": "Testing answer correctness, coverage, permissions, and update behavior.", "explanation": "Create expected paths for representative questions. Check that correct entities and evidence return, irrelevant versions and unauthorized sources are excluded, and unsupported relationships do not answer the question. Test removal and updates: retiring a source should make dependent assertions ineligible until reviewed.", "example": "Change a field and compare the impact list with a manually verified expected set.", "caution": "Absence of an edge is usually missing information, not proof that no relationship exists."}], "body": ["Graph evaluation includes structural validity and domain correctness. Check dangling IDs, duplicates, allowed types, and missing provenance. Then review whether the connected facts mean what the query assumes. If a guide only mentions an endpoint in passing, DOCUMENTS may exaggerate its coverage.", "For an AI assistant, use the query result as bounded evidence, possibly together with retrieved passages. Carry source IDs and applicability into context assembly and require the answer to distinguish observed relationships from unknowns. Keep authorization enforcement outside the model. Graph retrieval can complement semantic search, but it can also return misleading context if the model or evidence is stale.", "Operate the graph as a maintained knowledge product. Product changes trigger dependency review; source retirement triggers assertion review; ownership changes trigger handoff. Capture query misses and rejected extractions as feedback. Expand the schema only when new questions need it, and measure whether connected queries improve the actual task."], "workflow": ["Define expected answers and paths.", "Run graph queries with applicability and permission filters.", "Inspect returned evidence and missing coverage.", "Test source changes, retirement, and ownership handoff.", "Measure task value and revise the model."], "deep_dive": [], "annotated": {"code": "// Illustrative Cypher-style pattern; adapt to your engine/schema.\nMATCH (t:Topic)-[:DOCUMENTS]->(e:Endpoint)\nWHERE e.id = \"relay:v2:endpoint:create-job\"\nRETURN t.id, t.title\n\nNext: inspect approved evidence and version scope for each match.\nThen: follow Team -[:OWNS]-> Topic to route review.", "notes": ["The pattern depends on the defined relationship direction.", "Eligibility checks must be implemented in the actual query/application.", "A complete test compares the returned set against known expected topics."]}, "exercise": {"task": "The graph returns no affected topics after a field changes. List checks before reporting “no impact.”", "hint": "An empty graph result may reflect a failed join, filter, or incomplete corpus.", "solution": "Check entity identity, dependency coverage, relation direction, version filters, review status, permissions, and source freshness. Compare with a manual reference set. Report unknown coverage if the graph cannot support a no-impact conclusion."}, "example": {"title": "Relay documentation graph · fictional project", "content": "// Illustrative Cypher-style pattern; adapt to your engine/schema.\nMATCH (t:Topic)-[:DOCUMENTS]->(e:Endpoint)\nWHERE e.id = \"relay:v2:endpoint:create-job\"\nRETURN t.id, t.title\n\nNext: inspect approved evidence and version scope for each match.\nThen: follow Team -[:OWNS]-> Topic to route review."}, "lab": {"task": "The graph returns no affected topics after a field changes. List checks before reporting “no impact.”", "steps": ["Define expected answers and paths.", "Run graph queries with applicability and permission filters.", "Inspect returned evidence and missing coverage.", "Test source changes, retirement, and ownership handoff.", "Measure task value and revise the model."], "deliverable": "A saved graph-design artifact and a short explanation of its evidence and limitations."}, "checklist": ["The pattern depends on the defined relationship direction.", "Eligibility checks must be implemented in the actual query/application.", "A complete test compares the returned set against known expected topics.", "Every relationship has applicable evidence", "Proposed connections are distinct from approved facts"], "check": {"q": "An empty query result proves what?", "options": ["No real dependency exists", "Only that the query returned no matching eligible records under its current data and rules", "The graph is correct", "AI is unnecessary"], "answer": 1, "explanation": "Check entity identity, dependency coverage, relation direction, version filters, review status, permissions, and source freshness. Compare with a manual reference set. Report unknown coverage if the graph cannot support a no-impact conclusion."}, "sources": [["W3C RDF concepts", "https://www.w3.org/TR/rdf11-concepts/"]]}]}];
const glossary = [
  ['Abstention','A controlled decision not to answer or act when evidence, permission, or confidence is inadequate.'],['AI eligibility','A governed status defining whether and how content may be used by an AI system.'],['Canonical source','The designated source that governs a fact or decision in a defined context.'],['Chunk','A retrievable content unit with identifiers, metadata, and enough context for interpretation.'],['Content model','The semantic types, fields, relationships, and rules used to structure knowledge.'],['Decision record','A durable account of context, evidence, options, choice, owner, and revisit trigger.'],['Embedding','A numerical representation used to compare semantic similarity.'],['Entailment','Whether supplied evidence logically supports a specific claim.'],['Evaluation set','Versioned cases, evidence, expected behavior, and scoring rules used to test a system.'],['Groundedness','The degree to which answer claims are supported by eligible evidence.'],['Hybrid retrieval','Retrieval that combines filters, lexical, semantic, graph, authority, freshness, or behavioral signals.'],['Knowledge graph','A network of identifiable entities and typed relationships used for traversal, reasoning, and traceability.'],['LLM-as-a-judge','A model used to score outputs against explicit criteria and anchors, calibrated against trusted labels.'],['Metadata','Structured attributes describing content, context, status, relationships, and use.'],['Ontology','A shared model of entity types, relationship types, constraints, and domain meaning.'],['Provenance','Information about where knowledge came from, how it changed, and who authorized it.'],['RAG','Retrieval-augmented generation: selecting external evidence and supplying it to a model for grounded generation.'],['Regression','A previously acceptable behavior that worsens after a system change.'],['Reranking','A second-stage ordering of retrieved candidates using richer context and criteria.'],['Risk tier','A category based on consequence, reversibility, exposure, and regulatory or reputational risk.'],['Source authority','The right of a source to govern a claim or decision in a defined context.'],['Taxonomy','A governed vocabulary and classification structure for describing a domain consistently.'],['Test case','A question, context, expected behavior, evidence, and scoring rule.'],['Traceability','The ability to connect an answer back to evidence, source, owner, version, and system decisions.']
];

