function conceptTerm(c){return Array.isArray(c)?c[0]:c.term;}
function conceptDefinition(c){return Array.isArray(c)?c[1]:c.definition;}
function conceptSearch(c){return Array.isArray(c)?c.join(' '):[c.term,c.definition,c.explanation,c.example,c.caution].join(' ');}
function renderConcept(c,i){
 const term=conceptTerm(c),guide=(window.CONCEPT_GUIDES||{})[term];
 return `<section class="concept-explained"><span class="concept-label">CONCEPT ${i+1}</span><h3>${esc(term)}</h3><div class="concept-answer"><h4>What it is</h4><p class="concept-definition">${esc(conceptDefinition(c))}</p>${guide?`<h4>Plain-language mental model</h4><p>${esc(guide.plain)}</p><h4>Why it matters</h4><p>${esc(guide.why)}</p>`:''}${c.explanation?`<h4>How it works</h4><p>${esc(c.explanation)}</p>`:''}${guide?`<h4>How to use it</h4><p>${esc(guide.use)}</p>`:''}${c.example?`<h4>Concrete example</h4><p>${esc(c.example)}</p>`:''}${c.caution?`<aside class="callout warning"><strong>Common mistake</strong><p>${esc(c.caution)}</p></aside>`:''}</div></section>`;
}
function conceptConnection(l){const link=(window.LESSON_CONCEPT_LINKS||{})[l.id];return link?`<aside class="concept-connection"><span>CONCEPT MAP</span><h3>How these ideas connect</h3><p>${esc(link)}</p></aside>`:'';}
