 const idx=allLessons.findIndex(x=>x.id===id),prev=allLessons[idx-1],next=allLessons[idx+1];
 const sections=[['objectives','Objectives'],['concepts','What each concept means'],['method','How it works'],['annotated','Annotated example'],['exercise','Try it yourself'],['lab','Guided lab'],['checklist','Review checklist'],['knowledge-check','Knowledge check'],['playground','Hands-on playground'],['notes','Your workspace'],['references','References']];setToc(sections.filter(x=>(l.annotated||!['annotated','exercise'].includes(x[0]))&&(x[0]!=='playground'||['tw-5','kg-5','kg-6'].includes(l.id))).map(([id,label])=>({id,label})));
 const deep=(l.deep_dive||[]).map(d=>`<h3>${esc(d.title)}</h3>${d.paragraphs.map(x=>`<p>${esc(x)}</p>`).join('')}`).join('');
 const annotated=l.annotated?`<section class="lesson-section" id="annotated"><h2>Annotated example</h2><div class="code-wrap"><button class="copy-code button" type="button">Copy example</button><pre><code>${esc(l.annotated.code)}</code></pre></div><ol class="annotation-list">${l.annotated.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="exercise-note">Relay is a fictional teaching example. These checks validate the course fixture, not a live API.</p></section>`:'';
