 $('#content').innerHTML=`${pageHero({eyebrow:`${l.module.number} · ${l.module.title}`,title:l.title,dek:l.summary,meta:[l.time,l.level,`Lesson ${idx+1} of ${allLessons.length}`],crumb:l.module.title})}<article class="lesson-body"><section class="lesson-section" id="objectives"><h2>What you will learn</h2><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="lesson-section" id="concepts"><h2>Understand the concepts</h2><p class="section-intro">Each concept is explained from first principles: what it is, why it matters, how it works, and how to apply it.</p>\${conceptConnection(l)}\${l.concepts.map(renderConcept).join('')}</section><section class="lesson-section" id="method"><h2>How to apply it</h2>${l.body.map(x=>`<p>${esc(x)}</p>`).join('')}${deep}<h3>Step-by-step method</h3><ol class="workflow">${l.workflow.map(x=>`<li><span>${esc(x)}</span></li>`).join('')}</ol><div class="example-box"><div class="box-title">${esc(l.example.title)}</div><div class="box-content"><p>${esc(l.example.content)}</p></div></div></section>${l.id==='kg-1'?graphSvg(graphSample):''}${annotated}${exercise}${lessonSandbox(l)}<section class="lesson-section" id="lab"><h2>Guided practice lab</h2><p>${esc(l.lab.task)}</p>${l.lab.steps?`<ol>${l.lab.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}<div class="callout success"><strong>Your deliverable</strong><p>${esc(l.lab.deliverable)}</p></div></section><section class="lesson-section" id="checklist"><h2>Review your work</h2><ul class="checklist">${l.checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="lesson-check" id="knowledge-check"><h2>Knowledge check</h2><p>${esc(l.check.q)}</p><form class="check-form"><div class="check-options">${l.check.options.map((x,i)=>`<label class="check-option"><input type="radio" name="check" value="${i}"><span>${esc(x)}</span></label>`).join('')}</div><button class="button primary" type="submit">Check answer</button><div class="check-feedback" aria-live="polite"></div></form></section><section class="lesson-section" id="notes"><h2>Your practice workspace</h2><p>Write your response, paste your artifact, or record questions. Drafts stay in this browser; export a copy for safekeeping. Feedback from the button is a self-review checklist, not an AI grade.</p><label for="lesson-draft">Your draft for this lesson</label><textarea id="lesson-draft" rows="12" spellcheck="false"></textarea><div class="workspace-actions"><button class="button primary" id="save-draft">Save draft</button><button class="button" id="export-draft">Export draft</button><button class="button" id="review-draft">Review checklist</button></div><div id="draft-feedback" role="status"></div></section><section class="lesson-section" id="references"><h2>References and next steps</h2><ul>${(l.sources||[['Course sources','technical-writing-resources.html']]).map(([name,url])=>`<li><a href="${esc(url)}">${esc(name)}</a></li>`).join('')}</ul><p><a href="technical-writing-workbook.md">Source fixture, templates, and capstone rubric</a></p></section><nav class="lesson-actions">${prev?`<a class="button" href="#/lesson/${prev.id}">← Previous lesson</a>`:'<a class="button" href="#/home">Course overview</a>'}<button class="button ${state.completed.has(id)?'complete':'primary'} mark-complete">${state.completed.has(id)?'✓ Completed':'Mark lesson complete'}</button>${next?`<a class="button" href="#/lesson/${next.id}">Next: ${esc(next.title)} →</a>`:'<a class="button primary" href="#/assessment">Final assessment →</a>'}</nav></article>`;
 $('.check-form').addEventListener('submit',e=>{e.preventDefault();const chosen=e.currentTarget.querySelector('input:checked'),out=$('.check-feedback');if(!chosen){out.textContent='Choose an answer first.';return;}const good=Number(chosen.value)===l.check.answer;out.textContent=(good?'Correct. ':'Not quite. ')+l.check.explanation;out.style.color=good?'#17673f':'#9a3d35';});
