function renderGlossary(){
 setActive('');setToc([]);const terms=new Map(glossary.map(g=>[g[0],{term:g[0],definition:g[1]}]));for(const l of allLessons)for(const c of l.concepts)terms.set(conceptTerm(c),{...(Array.isArray(c)?{term:c[0],definition:c[1]}:c),lesson:l});const entries=[...terms.values()].sort((a,b)=>a.term.localeCompare(b.term));
 $('#content').innerHTML=pageHero({eyebrow:'Reference',title:'Concept reference',dek:'Plain-language definitions, explanations, examples, and links to the lessons that teach each concept.',meta:[`${entries.length} terms`],crumb:'Reference'})+`<div class="glossary-tools"><input id="glossary-filter" type="search" placeholder="Find a concept…" aria-label="Find a concept"></div><section class="glossary-list">${entries.map(c=>`<article class="glossary-item" data-text="${esc([c.term,c.definition,c.explanation||''].join(' ').toLowerCase())}"><h3>${esc(c.term)}</h3><p><strong>${esc(c.definition)}</strong></p>${c.explanation?`<p>${esc(c.explanation)}</p><h4>Example</h4><p>${esc(c.example)}</p><p><a href="#/lesson/${c.lesson.id}">Study this concept in its lesson →</a></p>`:''}</article>`).join('')}</section>`;$('#glossary-filter').addEventListener('input',e=>{const q=e.target.value.toLowerCase();$$('.glossary-item').forEach(x=>x.hidden=!!q&&!x.dataset.text.includes(q));});}

function renderAssessment(){
  setActive('');setToc([]);document.title='Final Assessment | Knowledge Graphs | Baseframe';
  const questions=allLessons.map((l,i)=>({...l.check,domain:l.module.title,n:i+1}));
  $('#content').innerHTML=`${pageHero({eyebrow:'Final assessment',title:'Test your knowledge graph understanding',dek:'Apply concepts across architecture, retrieval, evaluation, governance, and program delivery. Your result includes a domain-by-domain readiness profile.',meta:[`${questions.length} questions`,'80% recommended pass','Answers saved only for this attempt'],crumb:'Assessment'})}<section class="assessment-intro"><div class="assessment-stats"><div class="assessment-stat"><strong>${questions.length}</strong><span>scenario questions</span></div><div class="assessment-stat"><strong>6</strong><span>course chapters</span></div><div class="assessment-stat"><strong>80%</strong><span>recommended pass</span></div></div></section><form id="assessment-form">${questions.map(q=>`<article class="quiz-question"><small>${esc(q.domain)} · ${q.n}/${questions.length}</small><h3>${esc(q.q)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="q${q.n}" value="${i}"><span>${esc(o)}</span></label>`).join('')}</div></article>`).join('')}<div class="assessment-submit"><span id="answered-count">0 of ${questions.length} answered</span><button class="button primary" type="submit">Score my assessment</button></div></form><div id="assessment-result"></div>`;
  const form=$('#assessment-form');form.addEventListener('change',()=>{$('#answered-count').textContent=`${new FormData(form).keys?new Set([...new FormData(form).keys()]).size:0} of ${questions.length} answered`;});
  form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form),answered=new Set([...data.keys()]).size;if(answered<questions.length){showToast(`Answer all ${questions.length} questions before scoring`);return;}let correct=0;const domains={};questions.forEach(q=>{domains[q.domain]??={right:0,total:0};domains[q.domain].total++;if(Number(data.get('q'+q.n))===q.answer){correct++;domains[q.domain].right++;}});const pct=Math.round(correct/questions.length*100),pass=pct>=80;$('#assessment-result').innerHTML=`<section class="assessment-result"><div class="result-head"><div class="result-score">${pct}%</div><h2>${pass?'Strong systems foundation':'Keep building your systems judgment'}</h2><p>You answered ${correct} of ${questions.length} questions correctly. ${pass?'You demonstrated connected thinking across the course domains.':'Review the lowest-scoring domains, repeat their labs, and try again.'}</p></div><div class="result-body"><h3>Domain profile</h3><div class="domain-bars">${Object.entries(domains).map(([name,v])=>{const p=Math.round(v.right/v.total*100);return `<div class="domain-bar"><div><span>${esc(name)}</span><strong>${p}%</strong></div><div class="domain-bar-track"><span style="width:${p}%"></span></div></div>`}).join('')}</div><div class="callout ${pass?'success':'warning'}"><strong>${pass?'Recommended next step':'Focus area'}</strong><p>${pass?'Complete the capstone and its separate practical rubric. A quiz pass does not certify production competence.':'Start with the lowest domain above. Revisit its three lessons and complete each practice deliverable before retaking the assessment.'}</p></div><button class="button" type="button" id="retake">Retake assessment</button></div></section>`;$('#assessment-result').scrollIntoView({behavior:'smooth'});$('#retake').addEventListener('click',()=>{form.reset();$('#answered-count').textContent=`0 of ${questions.length} answered`;$('#assessment-result').innerHTML='';scrollTo({top:0,behavior:'smooth'});});});
}

function route(){
  if(location.hash && !location.hash.startsWith("#/")) return;
  const hash=location.hash||'#/home',parts=hash.replace(/^#\//,'').split('/');
  if(parts[0]==='lesson')renderLesson(parts[1]);else if(parts[0]==='case-study')renderCaseStudy();else if(parts[0]==='offers')renderOffers();else if(parts[0]==='glossary')renderGlossary();else if(parts[0]==='assessment')renderAssessment();else renderHome();
  $('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');scrollTo(0,0);$('#content').focus({preventScroll:true});
}

function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2200);}

function openSearch(){const d=$('#search-dialog');d.hidden=false;document.body.style.overflow='hidden';$('#search-input').value='';renderSearch('');setTimeout(()=>$('#search-input').focus(),20);}
function closeSearch(){const d=$('#search-dialog');d.hidden=true;document.body.style.overflow='';$('#search-trigger').focus();}
function renderSearch(query){
  const q=query.trim().toLowerCase();let matches=allLessons.filter(l=>!q||[l.title,l.summary,l.module.title,...l.objectives,...l.concepts.map(conceptSearch),...(l.deep_dive||[]).flatMap(d=>[d.title,...d.paragraphs])].join(' ').toLowerCase().includes(q));
  $('#search-results').innerHTML=matches.length?matches.slice(0,12).map(l=>`<a class="search-result" href="#/lesson/${l.id}"><small>${l.module.number} · ${esc(l.module.title)}</small><strong>${esc(l.title)}</strong><span>${esc(l.summary)}</span></a>`).join(''):`<div class="empty-search">No lessons match “${esc(query)}”. Try a term such as retrieval, metadata, evaluation, or governance.</div>`;
  $$('.search-result',$('#search-results')).forEach(a=>a.addEventListener('click',closeSearch));
}

renderNav();route();
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a && a.getAttribute('href')?.match(/^#[^/]/)){const target=document.getElementById(a.getAttribute('href').slice(1));if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth'});}}});
window.addEventListener('hashchange',route);
$('#mobile-menu').addEventListener('click',e=>{const open=$('#sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
$('#search-trigger').addEventListener('click',openSearch);$('#search-close').addEventListener('click',closeSearch);$('#search-input').addEventListener('input',e=>renderSearch(e.target.value));
$('#search-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)closeSearch();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'&&!$('#search-dialog').hidden)closeSearch();});
$('#reset-progress').addEventListener('click',()=>{if(confirm('Reset all completed lessons and start again?')){state.completed.clear();saveProgress();showToast('Progress reset');route();}});
